  1→//! Human-readable output formatter.
  2→//!
  3→//! Formats lint diagnostics for terminal display with optional color support.
  4→
  5→use super::LintFormatter;
  6→use crate::lint::{LintDiagnostic, Severity};
  7→use std::io::Write;
  8→
  9→/// Formats lint output for human consumption.
 10→pub struct HumanFormatter {
 11→    /// Whether to use colors (ANSI escape codes).
 12→    pub use_color: bool,
 13→}
 14→
 15→impl HumanFormatter {
 16→    /// Create a new human formatter.
 17→    pub fn new(use_color: bool) -> Self {
 18→        Self { use_color }
 19→    }
 20→
 21→    fn severity_prefix(&self, severity: Severity) -> &'static str {
 22→        match severity {
 23→            Severity::Hint => "hint",
 24→            Severity::Warning => "warning",
 25→            Severity::Error => "error",
 26→        }
 27→    }
 28→}
 29→
 30→impl LintFormatter for HumanFormatter {
 31→    fn format<W: Write>(
 32→        &self,
 33→        diagnostics: &[LintDiagnostic],
 34→        writer: &mut W,
 35→    ) -> std::io::Result<()> {
 36→        for diag in diagnostics {
 37→            // Header line: error[rule-id]: message
 38→            writeln!(
 39→                writer,
 40→                "{}[{}]: {}",
 41→                self.severity_prefix(diag.severity),
 42→                diag.rule_id.0,
 43→                diag.message
 44→            )?;
 45→
 46→            // Location line
 47→            if let Some(ref span) = diag.span {
 48→                writeln!(
 49→                    writer,
 50→                    "  --> {}:{}:{}",
 51→                    span.file.display(),
 52→                    span.start_line,
 53→                    span.start_col
 54→                )?;
 55→            }
 56→
 57→            // Suggestion
 58→            if let Some(ref suggestion) = diag.suggestion {
 59→                writeln!(writer, "   = help: {}", suggestion)?;
 60→            }
 61→
 62→            // Related info
 63→            for related in &diag.related {
 64→                writeln!(
 65→                    writer,
 66→                    "   = note: {} ({}:{})",
 67→                    related.message,
 68→                    related.span.file.display(),
 69→                    related.span.start_line
 70→                )?;
 71→            }
 72→
 73→            writeln!(writer)?;
 74→        }
 75→
 76→        // Summary
 77→        let error_count = diagnostics
 78→            .iter()
 79→            .filter(|d| d.severity == Severity::Error)
 80→            .count();
 81→        let warning_count = diagnostics
 82→            .iter()
 83→            .filter(|d| d.severity == Severity::Warning)
 84→            .count();
 85→
 86→        if error_count > 0 || warning_count > 0 {
 87→            writeln!(
 88→                writer,
 89→                "Found {} error(s) and {} warning(s)",
 90→                error_count, warning_count
 91→            )?;
 92→        }
 93→
 94→        Ok(())
 95→    }
 96→}
