196→
197→        let mut output = Vec::new();
198→        formatter.format(&diagnostics, &mut output).unwrap();
199→        let output = String::from_utf8(output).unwrap();
200→
201→        assert!(output.contains("= note: step_a defined here"));
202→        assert!(output.contains("config.yml:5"));
203→    }
204→
