28→            start_line: line,
29→            start_col: 1,
30→            end_line: line,
31→            end_col: usize::MAX,
32→        }
33→    }
34→
35→    /// Create a span with precise positions.
36→    pub fn new(
37→        file: impl Into<PathBuf>,
38→        start_line: usize,
39→        start_col: usize,
40→        end_line: usize,
41→        end_col: usize,
42→    ) -> Self {
