 1→//! Configuration validation and linting.
 2→//!
 3→//! This module provides comprehensive configuration validation through
 4→//! a pluggable rule-based system.
 5→//!
 6→//! # Overview
 7→//!
 8→//! The lint system consists of:
 9→//!
10→//! - **Rules** - Individual validation checks ([`LintRule`] trait)
11→//! - **Registry** - Collection of all available rules ([`RuleRegistry`])
12→//! - **Diagnostics** - Issue reports with severity and suggestions ([`LintDiagnostic`])
13→//!
14→//! # Example
15→//!
16→//! ```
17→//! use bivvy::lint::{RuleRegistry, RuleId, Severity};
18→//!
19→//! // Create a registry (empty for now, builtins added in later commits)
20→//! let registry = RuleRegistry::new();
21→//!
22→//! // Check if a rule exists
23→//! assert!(registry.get(&RuleId::new("nonexistent")).is_none());
24→//!
25→//! // Severity has ordering
26→//! assert!(Severity::Hint < Severity::Warning);
27→//! assert!(Severity::Warning < Severity::Error);
28→//! ```
29→
30→pub mod diagnostic;
31→pub mod fix;
32→pub mod output;
33→pub mod registry;
34→pub mod rule;
35→pub mod rules;
36→pub mod schema;
37→pub mod span;
