45→    AppNameRule, CircularDependencyRule, CircularRequirementDepRule, InstallTemplateMissingRule,
46→    RequiredFieldsRule, SelfDependencyRule, ServiceRequirementWithoutHintRule, TemplateInputsRule,
47→    UndefinedDependencyRule, UndefinedTemplateRule, UnknownRequirementRule,
48→};
