  1→//! Rule registry for managing lint rules.
  2→//!
  3→//! The [`RuleRegistry`] stores all available lint rules and provides
  4→//! methods for registering, retrieving, and iterating over them.
  5→
  6→use std::collections::HashMap;
  7→
  8→use super::rule::{LintRule, RuleId};
  9→use super::rules::{
 10→    AppNameRule, CircularDependencyRule, CircularRequirementDepRule,
 11→    CustomEnvironmentShadowsBuiltinRule, EnvironmentCircularDependencyRule,
 12→    EnvironmentDefaultWorkflowMissingRule, InstallTemplateMissingRule, RedundantEnvNullRule,
 13→    RedundantEnvironmentOverrideRule, RequiredFieldsRule, SelfDependencyRule,
 14→    ServiceRequirementWithoutHintRule, UndefinedDependencyRule, UnknownEnvironmentInOnlyRule,
 15→    UnknownEnvironmentInStepRule, UnknownRequirementRule, UnreachableEnvironmentOverrideRule,
 16→};
 17→use crate::requirements::registry::RequirementRegistry;
 18→
 19→/// Registry of all available lint rules.
 20→pub struct RuleRegistry {
 21→    rules: HashMap<RuleId, Box<dyn LintRule>>,
 22→}
 23→
 24→impl RuleRegistry {
 25→    /// Create a new empty registry.
 26→    pub fn new() -> Self {
 27→        Self {
 28→            rules: HashMap::new(),
 29→        }
 30→    }
 31→
 32→    /// Create a registry with all built-in rules.
 33→    ///
 34→    /// This registers all the default validation rules that come with Bivvy.
 35→    /// Requirement rules are registered with a default `RequirementRegistry`
 36→    /// (built-ins only); the lint command re-registers them with config-aware
 37→    /// custom requirements.
 38→    /// Note: Template-related rules (UndefinedTemplateRule, TemplateInputsRule)
 39→    /// require a Registry and must be registered separately.
 40→    pub fn with_builtins() -> Self {
 41→        let mut registry = Self::new();
 42→        registry.register(Box::new(AppNameRule));
 43→        registry.register(Box::new(RequiredFieldsRule));
 44→        registry.register(Box::new(CircularDependencyRule));
 45→        registry.register(Box::new(SelfDependencyRule));
 46→        registry.register(Box::new(UndefinedDependencyRule));
 47→        registry.register(Box::new(UnknownEnvironmentInStepRule));
 48→        registry.register(Box::new(UnknownEnvironmentInOnlyRule));
 49→        registry.register(Box::new(EnvironmentDefaultWorkflowMissingRule));
 50→        registry.register(Box::new(UnreachableEnvironmentOverrideRule));
 51→        registry.register(Box::new(CustomEnvironmentShadowsBuiltinRule));
 52→        registry.register(Box::new(RedundantEnvironmentOverrideRule));
 53→        registry.register(Box::new(RedundantEnvNullRule));
 54→        registry.register(Box::new(EnvironmentCircularDependencyRule));
 55→
 56→        // Requirement rules (registered with default RequirementRegistry;
 57→        // the lint command re-registers with config-aware custom requirements)
 58→        registry.register(Box::new(UnknownRequirementRule::new(
 59→            RequirementRegistry::new(),
 60→        )));
 61→        registry.register(Box::new(CircularRequirementDepRule::new(
 62→            RequirementRegistry::new(),
 63→        )));
 64→        registry.register(Box::new(InstallTemplateMissingRule::new(
 65→            RequirementRegistry::new(),
 66→        )));
 67→        registry.register(Box::new(ServiceRequirementWithoutHintRule::new(
 68→            RequirementRegistry::new(),
 69→        )));
 70→        registry
 71→    }
 72→
 73→    /// Register a lint rule.
 74→    pub fn register(&mut self, rule: Box<dyn LintRule>) {
 75→        self.rules.insert(rule.id(), rule);
 76→    }
 77→
 78→    /// Get a rule by ID.
 79→    pub fn get(&self, id: &RuleId) -> Option<&dyn LintRule> {
 80→        self.rules.get(id).map(|r| r.as_ref())
 81→    }
 82→
 83→    /// Iterate over all rules.
 84→    pub fn iter(&self) -> impl Iterator<Item = &dyn LintRule> {
 85→        self.rules.values().map(|r| r.as_ref())
 86→    }
 87→
 88→    /// Get the number of registered rules.
 89→    pub fn len(&self) -> usize {
 90→        self.rules.len()
 91→    }
 92→
 93→    /// Check if the registry is empty.
 94→    pub fn is_empty(&self) -> bool {
 95→        self.rules.is_empty()
 96→    }
 97→}
 98→
 99→impl Default for RuleRegistry {
100→    fn default() -> Self {
101→        Self::new()
102→    }
103→}
