 47→impl Command for ListCommand {
 48→    fn execute(&self, ui: &mut dyn UserInterface) -> Result<CommandResult> {
 49→        // Load configuration
 50→        let config = match load_merged_config(&self.project_root) {
 51→            Ok(c) => c,
 52→            Err(BivvyError::ConfigNotFound { .. }) => {
 53→                ui.error("No configuration found. Run 'bivvy init' first.");
 54→                return Ok(CommandResult::failure(2));
 55→            }
 56→            Err(e) => return Err(e),
 57→        };
 58→
 59→        // Apply config default_output when no CLI flag was explicitly set
 60→        if ui.output_mode() == OutputMode::Normal {
 61→            ui.set_output_mode(config.settings.default_output.into());
 62→        }
 63→
 64→        let theme = BivvyTheme::new();
 65→
 66→        // Resolve environment
 67→        let resolved_env = self.resolve_environment(&config);
 68→        let env_name = &resolved_env.name;
 69→
 70→        // Show environment info
 71→        ui.message(&format!(
 72→            "  {} {} ({})\n",
 73→            theme.key.apply_to("Environment:"),
 74→            theme.highlight.apply_to(env_name),
 75→            theme.dim.apply_to(resolved_env.source.to_string()),
 76→        ));
 77→
 78→        // Show steps
 79→        if !self.args.workflows_only {
 80→            ui.message(&format!("  {}", theme.key.apply_to("Steps:")));
 81→            for (name, step) in &config.steps {
 82→                // Check if step is skipped by only_environments
 83→                let skipped = !step.only_environments.is_empty()
 84→                    && !step.only_environments.iter().any(|e| e == env_name);
 85→
 86→                if skipped {
 87→                    ui.message(&format!(
 88→                        "    {} {}",
 89→                        theme.dim.apply_to(name),
 90→                        theme.dim.apply_to(format!("(skipped in {})", env_name)),
 91→                    ));
 92→                    continue;
 93→                }
 94→
 95→                // First line: step name with template/command detail
 96→                let detail = if let Some(ref template) = step.template {
 97→                    format!(
 98→                        " {}",
 99→                        theme.dim.apply_to(format!("(template: {})", template))
100→                    )
101→                } else if let Some(ref cmd) = step.command {
102→                    format!(
103→                        " {} {}",
104→                        theme.dim.apply_to("—"),
105→                        theme.command.apply_to(cmd)
106→                    )
107→                } else {
108→                    String::new()
109→                };
110→                ui.message(&format!("    {}{}", theme.highlight.apply_to(name), detail));
111→
112→                // Description or title
113→                if let Some(ref desc) = step.description {
114→                    ui.message(&format!("      {}", theme.dim.apply_to(desc)));
115→                } else if let Some(ref title) = step.title {
116→                    ui.message(&format!("      {}", theme.dim.apply_to(title)));
117→                }
118→
119→                // Dependency tree
120→                if !step.depends_on.is_empty() {
121→                    ui.message(&format!(
122→                        "      {} {}",
123→                        theme.dim.apply_to("└── depends on:"),
124→                        theme.dim.apply_to(step.depends_on.join(", "))
125→                    ));
126→                }
127→            }
128→
129→            if !self.args.steps_only {
130→                ui.message("");
131→            }
132→        }
133→
134→        // Show workflows
135→        if !self.args.steps_only {
136→            ui.message(&format!("  {}", theme.key.apply_to("Workflows:")));
137→            for (name, workflow) in &config.workflows {
138→                let arrow_steps = workflow.steps.join(" → ");
139→                ui.message(&format!(
140→                    "    {}{} {}",
141→                    theme.highlight.apply_to(name),
142→                    theme.dim.apply_to(":"),
143→                    theme.dim.apply_to(&arrow_steps),
144→                ));
145→
146→                if let Some(ref desc) = workflow.description {
147→                    ui.message(&format!("      {}", theme.dim.apply_to(desc)));
148→                }
149→            }
150→        }

