 54→impl Command for StatusCommand {
 55→    fn execute(&self, ui: &mut dyn UserInterface) -> Result<CommandResult> {
 56→        // Load configuration
 57→        let config = match load_merged_config(&self.project_root) {
 58→            Ok(c) => c,
 59→            Err(BivvyError::ConfigNotFound { .. }) => {
 60→                ui.error("No configuration found. Run 'bivvy init' first.");
 61→                return Ok(CommandResult::failure(2));
 62→            }
 63→            Err(e) => return Err(e),
 64→        };
 65→
 66→        // Apply config default_output when no CLI flag was explicitly set
 67→        if ui.output_mode() == OutputMode::Normal {
 68→            ui.set_output_mode(config.settings.default_output.into());
 69→        }
 70→
 71→        // Get project identity
 72→        let project_id = ProjectId::from_path(&self.project_root)?;
 73→
 74→        // Load state
 75→        let state = StateStore::load(&project_id)?;
 76→
 77→        let theme = BivvyTheme::new();
 78→
 79→        // Resolve environment
 80→        let resolved_env = self.resolve_environment(&config);
 81→
 82→        // Show header: ⛺ AppName — Status
 83→        let app_name = config.app_name.as_deref().unwrap_or("Bivvy Setup");
 84→        ui.message(&format!(
 85→            "\n  {} {} {} {}\n",
 86→            theme.header.apply_to("⛺"),
 87→            theme.highlight.apply_to(app_name),
 88→            theme.dim.apply_to("—"),
 89→            theme.dim.apply_to("Status"),
 90→        ));
 91→
 92→        // Show environment info
 93→        ui.message(&format!(
 94→            "  {} {} ({})",
