 1→//! Circular dependency detection.
 2→//!
 3→//! This rule detects circular dependencies between steps in the configuration.
 4→
 5→use std::collections::HashSet;
 6→
 7→use crate::config::BivvyConfig;
 8→use crate::lint::{LintDiagnostic, LintRule, RuleId, Severity};
 9→
10→/// Detects circular dependencies between steps.
11→pub struct CircularDependencyRule;
12→
13→impl LintRule for CircularDependencyRule {
14→    fn id(&self) -> RuleId {
15→        RuleId::new("circular-dependency")
16→    }
17→
18→    fn name(&self) -> &str {
19→        "Circular Dependency"
20→    }
21→
22→    fn description(&self) -> &str {
23→        "Detects circular dependencies in step depends_on"
24→    }
25→
26→    fn default_severity(&self) -> Severity {
27→        Severity::Error
28→    }
29→
30→    fn check(&self, config: &BivvyConfig) -> Vec<LintDiagnostic> {
31→        let mut diagnostics = Vec::new();
32→        let mut reported = HashSet::new();
33→
34→        // Use DFS to detect cycles from each starting point
35→        for step_name in config.steps.keys() {
36→            if let Some(cycle) = self.find_cycle(config, step_name) {
37→                // Only report each cycle once (by the first step in the cycle)
38→                let cycle_key = {
39→                    let mut sorted = cycle.clone();
40→                    sorted.sort();
41→                    sorted.join(",")
42→                };
43→                if !reported.contains(&cycle_key) {
44→                    reported.insert(cycle_key);
45→                    diagnostics.push(LintDiagnostic::new(
46→                        self.id(),
47→                        self.default_severity(),
48→                        format!("Circular dependency detected: {}", cycle.join(" -> ")),
49→                    ));
50→                }
51→            }
52→        }
53→
54→        diagnostics
55→    }
56→}
57→
58→impl CircularDependencyRule {
59→    fn find_cycle(&self, config: &BivvyConfig, start: &str) -> Option<Vec<String>> {
60→        let mut visited = HashSet::new();
61→        let mut path = Vec::new();
62→        self.dfs(config, start, &mut visited, &mut path)
63→    }
64→
65→    fn dfs(
66→        &self,
67→        config: &BivvyConfig,
68→        current: &str,
69→        visited: &mut HashSet<String>,
70→        path: &mut Vec<String>,
71→    ) -> Option<Vec<String>> {
72→        if path.contains(&current.to_string()) {
73→            path.push(current.to_string());
74→            return Some(path.clone());
75→        }
76→        if visited.contains(current) {
77→            return None;
78→        }
79→
80→        visited.insert(current.to_string());

