//! GitHub Actions output formatter.
//!
//! Formats lint diagnostics as [workflow commands](https://docs.github.com/en/actions/writing-workflows/choosing-what-your-workflow-does/workflow-commands-for-github-actions)
//! so that errors and warnings appear as inline annotations in pull request diffs.

use super::LintFormatter;
use crate::lint::{LintDiagnostic, Severity};
use std::io::Write;

/// Formats lint output as GitHub Actions workflow commands.
///
/// Each diagnostic becomes a `::error::`, `::warning::`, or `::notice::`
/// annotation that GitHub renders inline on pull request file diffs.
pub struct GithubActionsFormatter;

impl GithubActionsFormatter {
    /// Create a new GitHub Actions formatter.
    pub fn new() -> Self {
        Self
    }

    fn severity_command(severity: Severity) -> &'static str {
        match severity {
            Severity::Error => "error",
            Severity::Warning => "warning",
            Severity::Hint => "notice",
        }
    }
}

impl Default for GithubActionsFormatter {
    fn default() -> Self {
        Self::new()
    }
}

impl LintFormatter for GithubActionsFormatter {
    fn format<W: Write>(
        &self,
        diagnostics: &[LintDiagnostic],
        writer: &mut W,
    ) -> std::io::Result<()> {
        for diag in diagnostics {
            let command = Self::severity_command(diag.severity);

            // Build the optional parameters (file, line, col, title)
            let mut params = Vec::new();

            if let Some(ref span) = diag.span {
                params.push(format!("file={}", span.file.display()));
                params.push(format!("line={}", span.start_line));
                if span.start_col > 1 {
                    params.push(format!("col={}", span.start_col));
                }
                if span.end_line > span.start_line {
                    params.push(format!("endLine={}", span.end_line));
                }
            }

            params.push(format!("title={}", diag.rule_id.0));

            let params_str = params.join(",");

            writeln!(writer, "::{command} {params_str}::{}", diag.message)?;
        }

        Ok(())
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::lint::{RuleId, Span};

    #[test]
    fn formats_error_as_workflow_command() {
        let formatter = GithubActionsFormatter::new();
        let diagnostics = vec![LintDiagnostic::new(
            RuleId::new("circular-dependency"),
            Severity::Error,
            "Circular dependency detected",
        )
        .with_span(Span::line("config.yml", 15))];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert_eq!(
            output,
            "::error file=config.yml,line=15,title=circular-dependency::Circular dependency detected\n"
        );
    }

    #[test]
    fn formats_warning_as_workflow_command() {
        let formatter = GithubActionsFormatter::new();
        let diagnostics = vec![LintDiagnostic::new(
            RuleId::new("app-name"),
            Severity::Warning,
            "App name contains spaces",
        )];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert_eq!(
            output,
            "::warning title=app-name::App name contains spaces\n"
        );
    }

    #[test]
    fn formats_hint_as_notice() {
        let formatter = GithubActionsFormatter::new();
        let diagnostics = vec![LintDiagnostic::new(
            RuleId::new("style-hint"),
            Severity::Hint,
            "Consider using kebab-case",
        )];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert!(output.starts_with("::notice "));
    }

    #[test]
    fn includes_column_when_greater_than_one() {
        let formatter = GithubActionsFormatter::new();
        let diagnostics =
            vec![
                LintDiagnostic::new(RuleId::new("test"), Severity::Error, "msg")
                    .with_span(Span::new("config.yml", 10, 5, 10, 20)),
            ];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert!(output.contains("col=5"));
    }

    #[test]
    fn omits_column_one() {
        let formatter = GithubActionsFormatter::new();
        let diagnostics = vec![
            LintDiagnostic::new(RuleId::new("test"), Severity::Error, "msg")
                .with_span(Span::line("config.yml", 10)),
        ];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert!(!output.contains("col="));
    }

    #[test]
    fn includes_end_line_for_multiline_spans() {
        let formatter = GithubActionsFormatter::new();
        let diagnostics =
            vec![
                LintDiagnostic::new(RuleId::new("test"), Severity::Error, "msg")
                    .with_span(Span::new("config.yml", 10, 1, 15, 1)),
            ];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert!(output.contains("endLine=15"));
    }

    #[test]
    fn no_output_for_empty_diagnostics() {
        let formatter = GithubActionsFormatter::new();
        let diagnostics: Vec<LintDiagnostic> = vec![];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert!(output.is_empty());
    }

    #[test]
    fn formats_multiple_diagnostics() {
        let formatter = GithubActionsFormatter::new();
        let diagnostics = vec![
            LintDiagnostic::new(RuleId::new("r1"), Severity::Error, "error one")
                .with_span(Span::line("config.yml", 5)),
            LintDiagnostic::new(RuleId::new("r2"), Severity::Warning, "warning one"),
        ];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        let lines: Vec<&str> = output.lines().collect();
        assert_eq!(lines.len(), 2);
        assert!(lines[0].starts_with("::error "));
        assert!(lines[1].starts_with("::warning "));
    }

    #[test]
    fn without_span_only_has_title_param() {
        let formatter = GithubActionsFormatter::new();
        let diagnostics = vec![LintDiagnostic::new(
            RuleId::new("some-rule"),
            Severity::Error,
            "Something went wrong",
        )];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();
        let output = String::from_utf8(output).unwrap();

        assert_eq!(output, "::error title=some-rule::Something went wrong\n");
    }

    #[test]
    fn default_impl_works() {
        let formatter = GithubActionsFormatter::default();
        let diagnostics: Vec<LintDiagnostic> = vec![];

        let mut output = Vec::new();
        formatter.format(&diagnostics, &mut output).unwrap();

        assert!(output.is_empty());
    }
}
